package main
import("go/ast";"go/parser";"go/token";"os";"path/filepath";"fmt";"sort";"encoding/json")
func main(){dir:="/workspace/adamic/stage1/cohere/json"; fs:=token.NewFileSet(); graph:=map[string][]string{};loc:=map[string]string{}; entries,_:=os.ReadDir(dir);for _,entry:=range entries{if filepath.Ext(entry.Name())!=".go"{continue};f,err:=parser.ParseFile(fs,filepath.Join(dir,entry.Name()),nil,0);if err!=nil{panic(err)};for _,decl:=range f.Decls{fn,ok:=decl.(*ast.FuncDecl);if !ok{continue};name:=fn.Name.Name;p:=fs.Position(fn.Pos());loc[name]=fmt.Sprintf("stage1/cohere/json/%s:%d",entry.Name(),p.Line);ast.Inspect(fn.Body,func(n ast.Node)bool{if id,ok:=n.(*ast.Ident);ok{graph[name]=append(graph[name],id.Name)};return true})}}; b,_:=os.ReadFile("/tmp/u102/timing.json");var rows []struct{Test string `json:"test"`};json.Unmarshal(b,&rows); reached:=map[string]bool{};var visit func(string);visit=func(n string){if reached[n]||loc[n]==""{return};reached[n]=true;for _,next:=range graph[n]{visit(next)}};for _,row:=range rows{visit(row.Test)};visit("TestMain");var names []string;for n:=range reached{names=append(names,n)};sort.Strings(names);for _,n:=range names{fmt.Printf("%s %s\n",loc[n],n)}}
